'use strict';

// Staged server-side primitive; NOT yet wired into checkout or payment. A key
// is a 256-bit bearer capability generated by a cryptographically secure RNG.
// Store only its SHA-256 digest, never the raw key. Requests without the same
// key are not deduplicated, and cross-tab coordination is a separate problem.
const crypto=require('crypto');
const KEY='order_idempotency_schema_v1';
const DDL=`CREATE TABLE order_idempotency (
  key_hash TEXT PRIMARY KEY CHECK(length(key_hash) = 64),
  payload_hash TEXT NOT NULL CHECK(length(payload_hash) = 64),
  order_id TEXT NOT NULL UNIQUE REFERENCES orders(order_id) ON DELETE CASCADE,
  state TEXT NOT NULL CHECK(state IN ('CREATING','READY','FAILED','UNCERTAIN')),
  response_json TEXT,
  created_at_ms INTEGER NOT NULL CHECK(created_at_ms > 0),
  updated_at_ms INTEGER NOT NULL CHECK(updated_at_ms > 0)
)`;
const norm=s=>String(s||'').replace(/\s+/g,' ').trim().toLowerCase();
function ready(db){
 const t=db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name='order_idempotency'").get();
 const m=db.prepare('SELECT value FROM settings WHERE key=?').get(KEY);
 return !!(t&&norm(t.sql)===norm(DDL)&&m?.value==='1');
}
function install(db){return db.transaction(()=>{
 const t=db.prepare("SELECT sql FROM sqlite_master WHERE name='order_idempotency'").get();
 const m=db.prepare('SELECT value FROM settings WHERE key=?').get(KEY);
 if(t||m){if(ready(db))return {created:false};throw Error('Idempotency schema conflict');}
 db.exec(DDL);db.prepare('INSERT INTO settings(key,value) VALUES (?,?)').run(KEY,'1');return {created:true};
 }).immediate();}
function stableJson(v,depth=0){
 if(depth>24)throw Error('Request too deeply nested');
 if(v===null||typeof v==='boolean'||typeof v==='string')return JSON.stringify(v);
 if(typeof v==='number' && Number.isFinite(v))return JSON.stringify(v);
 if(Array.isArray(v))return '['+v.map(x=>stableJson(x,depth+1)).join(',')+']';
 if(typeof v==='object' && Object.getPrototypeOf(v)===Object.prototype)
  return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+stableJson(v[k],depth+1)).join(',')+'}';
 throw Error('Unsupported request value');
}
function fingerprint(key,payload){
 if(typeof key!=='string'||!/^[0-9a-f]{64}$/.test(key)||/^([0-9a-f])\1{63}$/.test(key))throw Error('Invalid idempotency key');
 if(!payload||Array.isArray(payload)||typeof payload!=='object')throw Error('Invalid request payload');
 const canonical=stableJson(payload);
 if(Buffer.byteLength(canonical)>128*1024)throw Error('Request too large');
 return {keyHash:crypto.createHash('sha256').update(key,'ascii').digest('hex'),payloadHash:crypto.createHash('sha256').update(canonical,'utf8').digest('hex')};
}
function validateHashes(keyHash,payloadHash){
 if(!/^[a-f0-9]{64}$/.test(keyHash||'')||!/^[a-f0-9]{64}$/.test(payloadHash||''))throw Error('Invalid digests');
}
function lookup(db,{keyHash,payloadHash}){
 if(!ready(db))throw Error('Idempotency schema unavailable');validateHashes(keyHash,payloadHash);
 const r=db.prepare('SELECT key_hash,payload_hash,order_id,state,response_json FROM order_idempotency WHERE key_hash=?').get(keyHash);
 if(!r)return {kind:'NEW'};
 if(!/^[a-f0-9]{64}$/.test(r.payload_hash||''))return {kind:'UNCERTAIN'};
 if(!crypto.timingSafeEqual(Buffer.from(r.payload_hash,'hex'),Buffer.from(payloadHash,'hex')))return {kind:'CONFLICT'};
 const o=db.prepare('SELECT status,payment_ref FROM orders WHERE order_id=?').get(r.order_id);
 if(!o)return {kind:'UNCERTAIN'};
 if(r.state==='READY' && o.status==='PENDING' && o.payment_ref){
  let response;try{response=JSON.parse(r.response_json)}catch{return {kind:'UNCERTAIN'}}
  if(!response || response.order_id!==r.order_id || response.authority!==o.payment_ref || typeof response.payment_url!=='string')return {kind:'UNCERTAIN'};
  const {authority,...safe}=response;return {kind:'READY',orderId:r.order_id,response:safe};
 }
 if(o.status==='PAID')return {kind:'PAID',orderId:r.order_id};
 if(r.state==='FAILED' && o.status==='FAILED')return {kind:'FAILED',orderId:r.order_id};
 return {kind:'UNCERTAIN',orderId:r.order_id};
}
// Caller MUST check lookup under BEGIN IMMEDIATE before inserting an order,
// then call bindNew in that same transaction. No provider call occurs inside.
function bindNew(db,{keyHash,payloadHash,orderId,nowMs=Date.now()}){
 if(!db.inTransaction)throw Error('Idempotency binding requires transaction');
 if(!ready(db))throw Error('Idempotency schema unavailable');validateHashes(keyHash,payloadHash);
 if(!Number.isSafeInteger(nowMs)||nowMs<=0||typeof orderId!=='string'||!orderId)throw Error('Invalid binding');
 if(lookup(db,{keyHash,payloadHash}).kind!=='NEW')throw Error('Idempotency key already bound');
 db.prepare(`INSERT INTO order_idempotency(key_hash,payload_hash,order_id,state,response_json,created_at_ms,updated_at_ms)
 VALUES(?,?,?,'CREATING',NULL,?,?)`).run(keyHash,payloadHash,orderId,nowMs,nowMs);
}
// Authority binding on the order and this update must share one transaction.
// Payment URL is produced by the trusted provider adapter, not user input.
function markReady(db,{keyHash,orderId,authority,response,nowMs=Date.now()}){
 if(!db.inTransaction)throw Error('Idempotency update requires transaction');
 if(!ready(db)||!/^[a-f0-9]{64}$/.test(keyHash||'')||!Number.isSafeInteger(nowMs)||nowMs<=0)throw Error('Invalid idempotency update');
 const o=db.prepare('SELECT status,payment_ref FROM orders WHERE order_id=?').get(orderId);
 if(!o||o.status!=='PENDING'||!authority||o.payment_ref!==authority)throw Error('Payment authority not bound');
 if(!response||response.order_id!==orderId||typeof response.payment_url!=='string'||!response.payment_url)throw Error('Invalid payment response');
 const saved=JSON.stringify({order_id:orderId,authority,payment_url:response.payment_url,subtotal:response.subtotal,
  discount:response.discount,discount_code:response.discount_code,shipping_fee:response.shipping_fee,
  gift_wrap_fee:response.gift_wrap_fee,total_payable:response.total_payable});
 const r=db.prepare("UPDATE order_idempotency SET state='READY',response_json=?,updated_at_ms=? WHERE key_hash=? AND order_id=? AND state='CREATING'")
  .run(saved,nowMs,keyHash,orderId);
 if(r.changes!==1)throw Error('Idempotency state conflict');
}
function markFailed(db,{keyHash,orderId,nowMs=Date.now()}){
 if(!db.inTransaction)throw Error('Idempotency update requires transaction');
 if(!ready(db)||!/^[a-f0-9]{64}$/.test(keyHash||'')||!Number.isSafeInteger(nowMs)||nowMs<=0)throw Error('Invalid idempotency update');
 const o=db.prepare('SELECT status FROM orders WHERE order_id=?').get(orderId);
 const state=o?.status==='FAILED'?'FAILED':'UNCERTAIN';
 const r=db.prepare("UPDATE order_idempotency SET state=?,response_json=NULL,updated_at_ms=? WHERE key_hash=? AND order_id=? AND state='CREATING'")
  .run(state,nowMs,keyHash,orderId);
 if(r.changes!==1)throw Error('Idempotency state conflict');
 return state;
}
module.exports={KEY,ready,install,fingerprint,lookup,bindNew,markReady,markFailed};
